package com.projexa.coaching.auth.security;
import com.projexa.coaching.common.tenant.TenantContextHolder; import io.jsonwebtoken.Claims; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.*;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtAuthenticationFilter(JwtService jwt){this.jwt=jwt;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){try{Claims c=jwt.parse(h.substring(7)); UUID user=UUID.fromString(c.getSubject()); UUID tenant=UUID.fromString(c.get("tenantId",String.class)); List<String> a=c.get("authorities",List.class); var auth=new UsernamePasswordAuthenticationToken(user,null,a==null?List.of():a.stream().map(x->new SimpleGrantedAuthority(x)).toList()); SecurityContextHolder.getContext().setAuthentication(auth); TenantContextHolder.set(tenant);}catch(Exception ignored){SecurityContextHolder.clearContext();}} try{chain.doFilter(req,res);}finally{TenantContextHolder.clear();}} }
